// ── STATE ──
let project = {
  name: 'Untitled Video',
  width: 1280, height: 720, fps: 30,
  clips: [],
  selectedClipId: null,
  currentTime: 0,
  duration: 10,
  isPlaying: false,
};
let zoom = 50; // pixels per second
let playInterval = null;

// ── CANVAS PREVIEW ──
const canvas = document.getElementById('previewCanvas');
const ctx = canvas.getContext('2d');

function resizeCanvas() {
  const rect = canvas.parentElement.getBoundingClientRect();
  canvas.width = rect.width * 0.8;
  canvas.height = rect.height * 0.8;
  renderFrame();
}

function renderFrame() {
  const w = canvas.width, h = canvas.height;
  ctx.fillStyle = '#0a0a14';
  ctx.fillRect(0, 0, w, h);

  // Draw checkerboard background
  ctx.fillStyle = '#111122';
  ctx.fillRect(0, 0, w, h);
  ctx.fillStyle = '#0f0f1e';
  for (let x = 0; x < w; x += 40) {
    for (let y = 0; y < h; y += 40) {
      if ((Math.floor(x/40) + Math.floor(y/40)) % 2 === 0) {
        ctx.fillRect(x, y, 40, 40);
      }
    }
  }

  // Find active clip at current time
  let activeClip = null;
  for (const clip of project.clips) {
    if (project.currentTime >= clip.start && project.currentTime < clip.start + clip.duration) {
      activeClip = clip;
      break;
    }
  }

  if (activeClip) {
    const clipTime = project.currentTime - activeClip.start;
    const progress = clipTime / activeClip.duration;

    ctx.save();

    // Apply clip effects
    const eff = activeClip.effects || {};
    const scale = (parseInt(eff.scale) || 100) / 100;
    const rotate = parseInt(eff.rotate) || 0;
    const opacity = (parseInt(eff.opacity) || 100) / 100;

    ctx.globalAlpha = opacity;
    ctx.translate(w / 2, h / 2);
    ctx.scale(scale, scale);
    ctx.rotate(rotate * Math.PI / 180);
    ctx.translate(-w / 2, -h / 2);

    // Draw clip content (generated gradient/pattern based on clip name)
    const grad = ctx.createLinearGradient(0, 0, w, h);
    const hue = (parseInt(String(activeClip.id).slice(-2), 36) * 37) % 360;
    grad.addColorStop(0, `hsl(${hue}, 40%, 20%)`);
    grad.addColorStop(1, `hsl(${(hue + 60) % 360}, 30%, 10%)`);
    ctx.fillStyle = grad;
    ctx.fillRect(20, 20, w - 40, h - 40);

    // Draw clip label
    ctx.fillStyle = `hsla(${hue}, 60%, 60%, 0.8)`;
    ctx.font = 'bold 24px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(activeClip.name, w / 2, h / 2 - 10);

    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    ctx.font = '16px Arial';
    ctx.fillText(`Clip ${activeClip.id} • ${activeClip.duration.toFixed(1)}s`, w / 2, h / 2 + 30);

    // Progress bar
    ctx.fillStyle = 'rgba(0,217,255,0.2)';
    ctx.fillRect(20, h - 40, w - 40, 8);
    ctx.fillStyle = '#00d9ff';
    ctx.fillRect(20, h - 40, (w - 40) * progress, 8);

    ctx.restore();

    // Apply brightness/contrast/saturation via canvas filter
    const brightness = parseInt(eff.brightness) || 100;
    const contrast = parseInt(eff.contrast) || 100;
    const saturation = parseInt(eff.saturation) || 100;
    // Note: in real implementation these would use pixel manipulation
  } else {
    ctx.fillStyle = 'rgba(255,255,255,0.05)';
    ctx.font = '18px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('No clip at current position', w / 2, h / 2);
  }

  // Time overlay
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(10, 10, 120, 24);
  ctx.fillStyle = '#00d9ff';
  ctx.font = '12px monospace';
  ctx.textAlign = 'left';
  ctx.fillText(formatTime(project.currentTime), 16, 26);
}

function formatTime(t) {
  const h = Math.floor(t / 3600);
  const m = Math.floor((t % 3600) / 60);
  const s = Math.floor(t % 60);
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
}

// ── TIMELINE ──
function renderTimeline() {
  const ruler = document.getElementById('timelineRuler');
  const track = document.getElementById('trackClips');
  const duration = project.duration || 10;
  const totalWidth = duration * zoom;

  // Ruler
  ruler.innerHTML = '';
  ruler.style.width = totalWidth + 'px';
  const step = zoom >= 100 ? 1 : zoom >= 50 ? 2 : zoom >= 25 ? 5 : 10;
  for (let t = 0; t <= duration; t += step) {
    const x = t * zoom;
    const div = document.createElement('div');
    div.style.cssText = `position:absolute;left:${x}px;top:0;font-size:9px;color:#444;transform:translateX(-50%)`;
    div.textContent = formatTime(t);
    ruler.appendChild(div);
    if (t > 0) {
      const line = document.createElement('div');
      line.style.cssText = `position:absolute;left:${x}px;top:18px;width:1px;height:14px;background:rgba(255,255,255,0.04)`;
      ruler.appendChild(line);
    }
  }

  // Track
  track.innerHTML = '';
  track.style.width = totalWidth + 'px';
  document.getElementById('clipCount').textContent = `${project.clips.length} clips`;

  for (const clip of project.clips) {
    const x = clip.start * zoom;
