const EMOJIS = ['🍎','🍊','🍋','🍇','🍓','🍒','🍑','🥝','🌮','🍕','🥓','🍔','🌭','🧁','🍩','🍪',
               '⚽','🏀','🏈','⚾','🎾','🏐','🏓','🥋','🎸','🎺','🎻','🥁','🎤','🎧','🎵','🎶'];
let grid = [];
let flipped = [];
let matched = [];
let moves = 0;
let timerInterval = null;
let seconds = 0;
let gridSize = 4;
let isProcessing = false;

function setDifficulty(size) {
  gridSize = size;
  document.querySelectorAll('.diff-btn').forEach(b => {
    b.classList.toggle('active', parseInt(b.dataset.size) === size);
  });
  resetGame();
}

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function resetGame() {
  clearInterval(timerInterval);
  timerInterval = null;
  seconds = 0;
  moves = 0;
  flipped = [];
  matched = [];
  isProcessing = false;
  document.getElementById('moves').textContent = '0';
  document.getElementById('timer').textContent = '0s';
  document.getElementById('winMessage').classList.remove('show');

  const totalPairs = (gridSize * gridSize) / 2;
  const emojis = EMOJIS.slice(0, totalPairs);
  grid = shuffle([...emojis, ...emojis]);
  document.getElementById('totalPairs').textContent = totalPairs;
  document.getElementById('pairs').textContent = '0';
  render();
}

function render() {
  const g = document.getElementById('grid');
  g.style.gridTemplateColumns = `repeat(${gridSize}, 1fr)`;
  g.innerHTML = '';
  grid.forEach((emoji, i) => {
    const card = document.createElement('div');
    card.className = 'card';
    if (matched.includes(i)) card.classList.add('matched');
    if (flipped.includes(i)) card.classList.add('flipped');
    card.dataset.index = i;
    card.innerHTML = `
      <span class="card-back">❓</span>
      <span class="card-emoji">${emoji}</span>
    `;
    card.onclick = () => flipCard(i);
    g.appendChild(card);
  });
}

function flipCard(index) {
  if (isProcessing) return;
  if (flipped.includes(index) || matched.includes(index)) return;
  if (flipped.length >= 2) return;

  if (!timerInterval) {
    timerInterval = setInterval(() => {
      seconds++;
      document.getElementById('timer').textContent = seconds + 's';
    }, 1000);
  }

  flipped.push(index);
  moves++;
  document.getElementById('moves').textContent = moves;
  render();

  if (flipped.length === 2) {
    isProcessing = true;
    const [i1, i2] = flipped;
    if (grid[i1] === grid[i2]) {
      matched.push(i1, i2);
      document.getElementById('pairs').textContent = matched.length / 2;
      flipped = [];
      isProcessing = false;
      render();
      if (matched.length === grid.length) {
        clearInterval(timerInterval);
        setTimeout(() => showWin(), 400);
      }
    } else {
      setTimeout(() => {
        flipped = [];
        isProcessing = false;
        render();
      }, 800);
    }
  }
}

function showWin() {
  const totalPairs = (gridSize * gridSize) / 2;
  const accuracy = Math.round((totalPairs / moves) * 100);
  document.getElementById('finalMoves').textContent = moves;
  document.getElementById('finalTime').textContent = seconds + 's';
  document.getElementById('finalAccuracy').textContent = accuracy + '%';
  document.getElementById('winMessage').classList.add('show');
}

function closeWin() {
  document.getElementById('winMessage').classList.remove('show');
  resetGame();
}

resetGame();

import { writeToFile } from './utils';
import { parseExpense, readFromFile } from './utils';

const expensesFilePath = 'expenses.json';

export async function addExpense(expense: { date: string; description: string; amount: number }) {
  const expenses = await loadExpenses();
  expenses.push(expense);
  await saveExpenses(expenses);
}

export async function listExpenses(): Promise<{ date: string; description: string; amount: number }[]> {
  return (await loadExpenses()).map(({ date, description, amount }) => ({ date, description, amount }));
}

export async function loadExpenses(): Promise<{ date: string; description: string; amount: number }[]> {
  try {
    const data = await readFromFile(expensesFilePath);
    return data.map((expense) => parseExpense(expense));
  } catch (err) {
    console.error('Failed to load expenses:', err);
    return [];
  }
}

export async function saveExpenses(expenses: { date: string; description: string; amount: number }[]) {
  try {
    await writeToFile(expensesFilePath, JSON.stringify(expenses, null, 2));
  } catch (err) {
    console.error('Failed to save expenses:', err);
  }
}

