import type { Game as GameContract } from '../types/types.ts';
import { Cell, GameEvent, GameException, GameResult, GameState, Move, Player } from '../types/types.ts';

const WIN_LINES: Array<[number, number, number]> = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8],
  [0, 3, 6], [1, 4, 7], [2, 5, 8],
  [0, 4, 8], [2, 4, 6],
];

export class Game implements GameContract {
  state: GameState;
  players: Player[];
  events: GameEvent[];
  result: GameResult | null;

  constructor() {
    this.state = { board: Array<Cell>(9).fill(null), currentPlayer: 'X' };
    this.players = [];
    this.events = [];
    this.result = null;
  }

  makeMove(move: Move): void {
    const index = move.row * 3 + move.col;
    if (index < 0 || index > 8 || this.state.board[index] !== null || this.result !== null) {
      throw new GameException(`Illegal move at ${move.row},${move.col}`);
    }
    this.state.board[index] = this.state.currentPlayer;
    this.state.currentPlayer = this.state.currentPlayer === 'X' ? 'O' : 'X';
    this.checkWin();
    this.checkTie();
  }

  checkWin(): void {
    const b = this.state.board;
    for (const [a, c, d] of WIN_LINES) {
      if (b[a] !== null && b[a] === b[c] && b[a] === b[d]) {
        this.result = { winner: b[a], line: [a, c, d] };
        return;
      }
    }
  }

  checkTie(): void {
    if (this.result === null && this.state.board.every((cell) => cell !== null)) {
      this.result = { winner: null, line: null };
    }
  }

  reset(): void {
    this.state = { board: Array<Cell>(9).fill(null), currentPlayer: 'X' };
    this.events = [];
    this.result = null;
  }
}

