const ROWS = 6, COLS = 7;
let board, currentPlayer, gameActive, scores;

function init() {
  board = Array.from({length: ROWS}, () => Array(COLS).fill(null));
  currentPlayer = 'red';
  gameActive = true;
  scores = { red: 0, yellow: 0, draw: 0 };
  render();
  updateStatus();
}

function render() {
  const boardEl = document.getElementById('board');
  boardEl.innerHTML = '';
  for (let c = 0; c < COLS; c++) {
    const col = document.createElement('div');
    col.className = 'col';
    col.dataset.col = c;
    for (let r = ROWS-1; r >= 0; r--) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      cell.dataset.row = r;
      cell.dataset.col = c;
      if (board[r][c] === 'red') cell.classList.add('red');
      else if (board[r][c] === 'yellow') cell.classList.add('yellow');
      col.appendChild(cell);
    }
    col.addEventListener('click', () => handleClick(c));
    boardEl.appendChild(col);
  }
}

function handleClick(col) {
  if (!gameActive) return;
  for (let r = 0; r < ROWS; r++) {
    if (!board[r][col]) {
      board[r][col] = currentPlayer;
      render();
      if (checkWin(r, col)) {
        gameActive = false;
        scores[currentPlayer]++;
        updateScores();
        highlightWins(r, col);
        document.getElementById('status').textContent = currentPlayer.charAt(0).toUpperCase() + currentPlayer.slice(1) + ' wins!';
        Array.from(document.querySelectorAll('.col')).forEach(c => c.classList.add('game-over'));
        return;
      }
      if (board.every(row => row.every(cell => cell !== null))) {
        gameActive = false;
        scores.draw++;
        updateScores();
        document.getElementById('status').textContent = "It's a draw!";
        Array.from(document.querySelectorAll('.col')).forEach(c => c.classList.add('game-over'));
        return;
      }
      currentPlayer = currentPlayer === 'red' ? 'yellow' : 'red';
      updateStatus();
      return;
    }
  }
}

function checkWin(row, col) {
  const directions = [[0,1],[1,0],[1,1],[1,-1]];
  return directions.some(([dr, dc]) => {
    let count = 1;
    for (let dir = -1; dir <= 1; dir += 2) {
      let r = row + dr * dir, c = col + dc * dir;
      while (r >= 0 && r < ROWS && c >= 0 && c < COLS && board[r][c] === currentPlayer) {
        count++;
        r += dr * dir;
        c += dc * dir;
      }
    }
    return count >= 4;
  });
}

function highlightWins(row, col) {
  const directions = [[0,1],[1,0],[1,1],[1,-1]];
  directions.forEach(([dr, dc]) => {
    const cells = [[row, col]];
    for (let dir = -1; dir <= 1; dir += 2) {
      let r = row + dr * dir, c = col + dc * dir;
      while (r >= 0 && r < ROWS && c >= 0 && c < COLS && board[r][c] === currentPlayer) {
        cells.push([r, c]);
        r += dr * dir;
        c += dc * dir;
      }
    }
    if (cells.length >= 4) {
      cells.forEach(([r, c]) => {
        const cell = document.querySelector(`.cell[data-row="${r}"][data-col="${c}"]`);
        if (cell) cell.classList.add('win');
      });
    }
  });
}

function resetGame() {
  board = Array.from({length: ROWS}, () => Array(COLS).fill(null));
  currentPlayer = 'red';
  gameActive = true;
  render();
  updateStatus();
}

function updateStatus() {
  document.getElementById('status').textContent = currentPlayer.charAt(0).toUpperCase() + currentPlayer.slice(1) + "'s turn";
}

function updateScores() {
  document.getElementById('scoreRed').textContent = scores.red;
  document.getElementById('scoreYellow').textContent = scores.yellow;
  document.getElementById('scoreDraw').textContent = scores.draw;
}

