function highlightCode(code, lang) {
  let html = escapeHTML(code);
  // Comments
  html = html.replace(/(\/\/.*)/g, '<span style="color:#6a737d">$1</span>');
  html = html.replace(/\/\*[\s\S]*?\*\//g, m => '<span style="color:#6a737d">' + escapeHTML(m) + '</span>');
  // Strings
  html = html.replace(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|`(?:[^`\\]|\\.)*`)/g, '<span style="color:#9ecbff">$1</span>');
  // Numbers
  html = html.replace(/\b(\d+\.?\d*)\b/g, '<span style="color:#f5a623">$1</span>');
  // Keywords
  if (lang === 'javascript') {
    html = html.replace(/\b(const|let|var|function|return|if|else|for|while|do|switch|case|break|continue|new|this|class|import|export|from|async|await|try|catch|throw|typeof|instanceof|of|in|true|false|null|undefined|NaN)\b/g, '<span style="color:#c678dd">$1</span>');
    html = html.replace(/\b(console|Array|Object|String|Number|Promise|setTimeout|setInterval|fetch|JSON|Math)\b/g, '<span style="color:#e5c07b">$1</span>');
  } else if (lang === 'html') {
    html = html.replace(/(&lt;\/?)(\w+)/g, '$1<span style="color:#e06c75">$2</span>');
    html = html.replace(/(\b\w+)(=)&quot;/g, '<span style="color:#56b6c2">$1</span>$2');
  } else if (lang === 'css') {
    html = html.replace(/([\w-]+)(?=\s*:)/g, '<span style="color:#e06c75">$1</span>');
    html = html.replace(/:(#[\da-fA-F]{3,8}|[\w-]+)/g, '<span style="color:#56b6c2">:$1</span>');
  }
  // Braces
  html = html.replace(/([{}[\]()])/g, '<span style="color:#abb2bf">$1</span>');
  return html || '<span style="color:#888">Start coding...</span>';
}

