}

function deleteFile(name) {
  if (fileOrder.length <= 1) return;
  if (!confirm(`Delete ${name}?`)) return;
  delete files[name];
  fileOrder = fileOrder.filter(f => f !== name);
  if (currentFile === name) switchFile(fileOrder[0]);
  renderFileTree();
  renderTabs();
}

function switchFile(name) {
  currentFile = name;
  const file = files[name];
  if (!file) return;
  document.getElementById('codeEditor').value = file.content;
  updateLineNumbers();
  renderTabs();
  renderFileTree();
}

function onCodeChange() {
  const file = files[currentFile];
  if (file) file.content = document.getElementById('codeEditor').value;
  updateLineNumbers();
}

function getFileIcon(name) {
  const ext = name.split('.').pop();
  return { html: '🌐', js: '📜', css: '🎨', json: '📋', txt: '📄', jsx: '⚛️', ts: '🦾' }[ext] || '📄';
}

