function renderFileTree() {
  const tree = document.getElementById('fileTree');
  tree.innerHTML = '<div class="ft-header">📁 Project Files</div>';
  for (const name of fileOrder) {
    const f = files[name];
    if (!f) continue;
    const div = document.createElement('div');
    div.className = 'file-item' + (name === currentFile ? ' active' : '');
    div.innerHTML = `<span class="icon">${getFileIcon(name)}</span>${name}`;
    div.onclick = () => switchFile(name);
    div.oncontextmenu = (e) => { e.preventDefault(); if (confirm(`Delete ${name}?`)) deleteFile(name); };
    tree.appendChild(div);
  }
}

function renderTabs() {
  const bar = document.getElementById('tabBar');
  bar.innerHTML = '';
  for (const name of fileOrder) {
    if (!files[name]) continue;
    const tab = document.createElement('div');
    tab.className = 'tab' + (name === currentFile ? ' active' : '');
    tab.innerHTML = `${getFileIcon(name)} ${name} <span class="close" onclick="event.stopPropagation();deleteFile('${name}')">×</span>`;
    tab.onclick = () => switchFile(name);
    bar.appendChild(tab);
  }
}

