      const d = new Date(); d.setDate(d.getDate() - i);
      const k = getDateKey(d);
      const done = h.log && h.log[k];
      let cls = 'heatmap-cell';
      if (done) { const str = getStreakForDay(h, d); cls += ' done-' + Math.min(5, Math.ceil(str / 3) + 1); }
      html += `<div class="${cls}" title="${k}: ${done ? '✓' : '✗'}"></div>`;
    }
    html += '</div></div>';
  });
  html += '</div>';
  container.innerHTML = html;
}

function getStreakForDay(habit, date) {
  let streak = 0;
  const d = new Date(date);
  while (true) {
    const key = getDateKey(d);
    if (habit.log && habit.log[key]) { streak++; d.setDate(d.getDate() - 1); }
    else break;
  }
  return streak;
}

