  const ambiguous = 'il1Lo0O';
  let chars = '';
  if (document.getElementById('optUpper').checked) chars += upper;
  if (document.getElementById('optLower').checked) chars += lower;
  if (document.getElementById('optDigits').checked) chars += digits;
  if (document.getElementById('optSymbols').checked) chars += symbols;
  if (!document.getElementById('optAmbiguous').checked) {
    for (const c of ambiguous) chars = chars.replaceAll(c, '');
  }
  if (!chars) { document.getElementById('passwordOutput').value = 'Select options!'; return; }
  let pwd = '';
