    <div class="chip"><b>${byLevel.simple?.passed ?? 0}/${byLevel.simple?.done ?? 0}</b>simple</div>
    <div class="chip"><b>${byLevel.hard?.passed ?? 0}/${byLevel.hard?.done ?? 0}</b>hard</div>
    <div class="chip"><b>${byLevel.extreme?.passed ?? 0}/${byLevel.extreme?.done ?? 0}</b>extreme</div>
    <div class="chip"><b>${(DATA.fixes || []).length}</b>datasheet fixes</div>`;
}

function outcomeClass(b) {
  if (b.passed && b.repairs) return 'patch';
  return b.passed ? 'pass' : 'fail';
}
function outcomeLabel(b) {
  if (b.passed && b.repairs) return `PASS +${b.repairs} repair${b.repairs > 1 ? 's' : ''}`;
  return b.passed ? 'PASS' : 'FAIL';
}

function fixFor(id) {
  return (DATA.fixes || []).filter(f => f.id === id);
}

function render() {
  document.getElementById('chips').innerHTML = chips();
  document.getElementById('status').innerHTML =
    `<span>Updated ${DATA.updated}</span>` +
    `<span>Dataset: <a href="/api/build-ladder/dataset" target="_blank">round9-buildladder.jsonl</a></span>` +
    `<span class="live">● API live</span>`;

  let list = (DATA.builds || []).slice();
  if (filter === 'fails') list = list.filter(b => !b.passed);
  else if (filter === 'repaired') list = list.filter(b => b.passed && (b.repairs || b.autoPatch));
  else if (filter !== 'all') list = list.filter(b => b.level === filter);
  if (query) {
    const q = query.toLowerCase();
    list = list.filter(b => (b.request || '').toLowerCase().includes(q) || (b.id || '').toLowerCase().includes(q));
  }
  document.getElementById('empty').style.display = list.length ? 'none' : 'block';
  document.getElementById('grid').innerHTML = list.map(cardHtml).join('');
}

function cardHtml(b) {
  const fixes = fixFor(b.id);
  const fixNote = fixes.length
    ? `<div class="detail"><b>Diagnosis:</b> ${escapeHtml(fixes[0].diagnosis || fixes[0].error || '').slice(0, 220)}</div>`
    : '';
  const kept = !b.passed ? `
    <button class="btn" onclick="showFiles('${b.id}')">View export</button>
    <button class="btn primary" onclick="retest('${b.id}', this)">Re-test now</button>` : '';
  return `
    <div class="card">
      <div class="top">
        <span class="id">${b.id}</span>
        <span class="lvl ${b.level}">${b.level}</span>
        <span class="lang">${b.lang}</span>
        <span class="outcome ${outcomeClass(b)}">${outcomeLabel(b)}</span>
      </div>
      <div class="request">${escapeHtml(b.request || '').slice(0, 160)}</div>
      <div class="meta">${b.attempts} attempt${b.attempts > 1 ? 's' : ''}${b.repairs ? ' · ' + b.repairs + ' repair(s)' : ''}${b.autoPatch ? ' · auto-patch: ' + escapeHtml(b.autoPatch.slice(0, 60)) : ''}</div>
      ${b.detail && !b.passed ? `<div class="detail">${escapeHtml((b.detail || '').slice(0, 200))}</div>` : ''}
      ${fixNote}
      <div class="actions">${kept}</div>
    </div>`;
}

function escapeHtml(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

async function showFiles(id) {
  const m = document.getElementById('modal');
  document.getElementById('modalTitle').textContent = id + ' — kept export';
  document.getElementById('modalBody').innerHTML = 'Loading files…';
  m.classList.add('open');
  try {
    const r = await fetch('/api/build-ladder/files/' + id);
    const d = await r.json();
    if (!r.ok) throw new Error(d.error || 'failed');
    document.getElementById('modalBody').innerHTML = d.files.map(f => `
      <b>${escapeHtml(f.path)}</b> (${f.size} bytes)
      <pre>${escapeHtml(f.content.slice(0, 4000))}</pre>`).join('') || '<i>no files</i>';
  } catch (e) {
    document.getElementById('modalBody').innerHTML = '<div class="empty">' + e.message + '</div>';
  }
}

async function retest(id, btn) {
  btn.disabled = true;
  const orig = btn.textContent;
  btn.textContent = 'Testing…';
  try {
    const r = await fetch('/api/build-ladder/retest/' + id, { method: 'POST' });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error || 'retest failed');
    const box = document.createElement('div');
    box.id = 'retestResult';
    box.className = d.ok ? 'ok' : 'bad';
    box.innerHTML = `<b>${d.ok ? '✅ PASS' : '❌ FAIL'}</b> — ${escapeHtml(d.detail || '')}` +
      (d.out ? `<pre style="max-height:160px;overflow:auto;margin-top:6px">${escapeHtml(d.out)}</pre>` : '');
    btn.closest('.actions').appendChild(box);
    setTimeout(() => box.remove(), 20000);
    if (d.ok) await load();
  } catch (e) {
    alert('Retest error: ' + e.message);
  } finally {
    btn.disabled = false;
    btn.textContent = orig;
  }
}

