function drawLineChart(canvas,data){
  const ctx=canvas.getContext('2d');
  const rect=canvas.parentElement.getBoundingClientRect();
  canvas.width=rect.width||500;canvas.height=220;
  const w=canvas.width,h=canvas.height,pad={top:15,right:15,bottom:25,left:45};
  const cw=w-pad.left-pad.right,ch=h-pad.top-pad.bottom;

  ctx.clearRect(0,0,w,h);
  ctx.fillStyle='#0a0a14';ctx.fillRect(0,0,w,h);

  const vals=data.data.map(d=>d.value);
  const min=Math.min(...vals)*0.95,max=Math.max(...vals)*1.05;

  // Grid
  ctx.strokeStyle='rgba(255,255,255,0.03)';ctx.lineWidth=1;
  for(let i=0;i<=4;i++){
    const y=pad.top+(ch/4)*i;
    ctx.beginPath();ctx.moveTo(pad.left,y);ctx.lineTo(w-pad.right,y);ctx.stroke();
    ctx.fillStyle='#444';ctx.font='9px Arial';ctx.textAlign='right';
    ctx.fillText(Math.round(max-(max-min)/4*i).toLocaleString(),pad.left-4,y+3);
  }

  // Area
  const points=vals.map((v,i)=>({x:pad.left+(i/(vals.length-1))*cw,y:pad.top+ch-(v-min)/ (max-min)*ch}));
  ctx.beginPath();ctx.moveTo(points[0].x,pad.top+ch);
  points.forEach(p=>ctx.lineTo(p.x,p.y));
  ctx.lineTo(points[points.length-1].x,pad.top+ch);
  ctx.closePath();
  const grad=ctx.createLinearGradient(0,pad.top,0,pad.top+ch);
  grad.addColorStop(0,'rgba(0,217,255,0.15)');grad.addColorStop(1,'rgba(0,217,255,0)');
  ctx.fillStyle=grad;ctx.fill();

  // Line
  ctx.beginPath();points.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));
  ctx.strokeStyle='#00d9ff';ctx.lineWidth=2.5;ctx.stroke();

  // Dots
  points.forEach((p,i)=>{
    ctx.beginPath();ctx.arc(p.x,p.y,4,0,Math.PI*2);
    ctx.fillStyle='#00d9ff';ctx.fill();
    ctx.beginPath();ctx.arc(p.x,p.y,6,0,Math.PI*2);
    ctx.strokeStyle='rgba(0,217,255,0.2)';ctx.lineWidth=2;ctx.stroke();

    // X labels
    if(i%2===0||i===vals.length-1){
      ctx.fillStyle='#555';ctx.font='8px Arial';ctx.textAlign='center';
      ctx.fillText(data.data[i].month,p.x,pad.top+ch+14);
    }
  });
}

function drawBarChart(canvas,data){
  const ctx=canvas.getContext('2d');
  const rect=canvas.parentElement.getBoundingClientRect();
  canvas.width=rect.width||500;canvas.height=220;
  const w=canvas.width,h=canvas.height,pad={top:15,right:15,bottom:25,left:45};
  const cw=w-pad.left-pad.right,ch=h-pad.top-pad.bottom;

  ctx.clearRect(0,0,w,h);
  ctx.fillStyle='#0a0a14';ctx.fillRect(0,0,w,h);

  const vals=data.data.slice(0,8);
  const maxVal=Math.max(...vals.map(d=>d.value));
  const barW=cw/vals.length*0.7;
  const gap=cw/vals.length*0.3;

  ctx.strokeStyle='rgba(255,255,255,0.03)';ctx.lineWidth=1;
  for(let i=0;i<=4;i++){const y=pad.top+(ch/4)*i;ctx.beginPath();ctx.moveTo(pad.left,y);ctx.lineTo(w-pad.right,y);ctx.stroke()}

  vals.forEach((d,i)=>{
    const barH=(d.value/maxVal)*ch*0.9;
    const x=pad.left+i*(barW+gap)+gap/2;
    const y=pad.top+ch-barH;
    const color=COLORS[i%COLORS.length];

    const grad=ctx.createLinearGradient(x,y,x,pad.top+ch);
    grad.addColorStop(0,color);grad.addColorStop(1,color+'44');
    ctx.fillStyle=grad;
    ctx.beginPath();ctx.roundRect(x,y,barW,barH,3);ctx.fill();

    ctx.fillStyle='#555';ctx.font='8px Arial';ctx.textAlign='center';
    ctx.fillText(d.month,x+barW/2,pad.top+ch+14);

    if(barH>20){
      ctx.fillStyle='#fff';ctx.font='8px Arial';ctx.textAlign='center';
      ctx.fillText(Math.round(d.value/1000)+'k',x+barW/2,y-5);
    }
  });
}

