function generatePassword() {
  const len = parseInt(document.getElementById('lengthRange').value);
  const upper = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const lower = 'abcdefghijklmnopqrstuvwxyz';
  const digits = '0123456789';
  const symbols = '!@#$%^&*()_+-=[]{}|;:,.<>?';
  const ambiguous = 'il1Lo0O';
  let chars = '';
  if (document.getElementById('optUpper').checked) chars += upper;
  if (document.getElementById('optLower').checked) chars += lower;
  if (document.getElementById('optDigits').checked) chars += digits;
  if (document.getElementById('optSymbols').checked) chars += symbols;
  if (!document.getElementById('optAmbiguous').checked) {
    for (const c of ambiguous) chars = chars.replaceAll(c, '');
  }
  if (!chars) { document.getElementById('passwordOutput').value = 'Select options!'; return; }
  let pwd = '';
  for (let i = 0; i < len; i++) pwd += chars[Math.floor(Math.random() * chars.length)];
  document.getElementById('passwordOutput').value = pwd;
  updateStrength(pwd);
}

function updateLength(val) {
  document.getElementById('lenVal').textContent = val;
  generatePassword();
}

function updateStrength(pwd) {
  let score = 0;
  if (pwd.length >= 8) score += 20;
  if (pwd.length >= 12) score += 15;
  if (pwd.length >= 16) score += 15;
  if (/[a-z]/.test(pwd) && /[A-Z]/.test(pwd)) score += 15;
  if (/\d/.test(pwd)) score += 10;
  if (/[^a-zA-Z0-9]/.test(pwd)) score += 15;
  if (/(.)\1{2,}/.test(pwd)) score -= 10;
  score = Math.max(0, Math.min(100, score));
  const fill = document.getElementById('strengthFill');
  const label = document.getElementById('strengthLabel');
  if (score < 25) { fill.style.width = score + '%'; fill.style.background = '#f87171'; label.textContent = 'Weak'; label.style.color = '#f87171'; }
  else if (score < 50) { fill.style.width = score + '%'; fill.style.background = '#fb923c'; label.textContent = 'Fair'; label.style.color = '#fb923c'; }
  else if (score < 75) { fill.style.width = score + '%'; fill.style.background = '#fbbf24'; label.textContent = 'Good'; label.style.color = '#fbbf24'; }
  else { fill.style.width = score + '%'; fill.style.background = '#4ade80'; label.textContent = 'Strong'; label.style.color = '#4ade80'; }
}

