function renderVault() {
  const search = document.getElementById('vaultSearch').value.toLowerCase();
  const filter = document.getElementById('vaultFilter').value;
  const list = document.getElementById('entryList');
  document.getElementById('entryCount').textContent = vault.length + ' entries';
  let filtered = vault;
  if (filter !== 'all') filtered = filtered.filter(e => e.category === filter);
  if (search) filtered = filtered.filter(e => e.site.toLowerCase().includes(search) || e.username.toLowerCase().includes(search));
  if (filtered.length === 0) {
    list.innerHTML = '<div class="empty-vault">🔍 No matching entries found</div>'; return;
  }
  list.innerHTML = filtered.map(entry => `
    <div class="entry-item">
      <div class="entry-icon">${CATEGORY_ICONS[entry.category] || '📦'}</div>
      <div class="entry-info">
        <div class="entry-site">${escapeHTML(entry.site)}</div>
        <div class="entry-username">${escapeHTML(entry.username)}</div>
        <span class="entry-category">${escapeHTML(entry.category)}</span>
      </div>
      <div class="entry-password" onclick="togglePasswordVisible('${entry.id}')" id="pwd-${entry.id}">${'•'.repeat(Math.min(20, (entry.password || '').length))}</div>
      <div class="entry-actions">
        <button class="btn-sm" onclick="editEntry('${entry.id}')">✏️</button>
        <button class="btn-sm danger" onclick="deleteEntry('${entry.id}')">🗑️</button>
      </div>
    </div>
  `).join('');
}

let passwordVisible = {};
function togglePasswordVisible(id) {
  const entry = vault.find(e => e.id === id);
  if (!entry) return;
  passwordVisible[id] = !passwordVisible[id];
  const el = document.getElementById('pwd-' + id);
  if (el) el.textContent = passwordVisible[id] ? entry.password : '•'.repeat(Math.min(20, (entry.password || '').length));
}

function escapeHTML(str) {
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
}

