const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
const WIDTH = 800, HEIGHT = 500;
canvas.width = WIDTH;
canvas.height = HEIGHT;

let isDrawing = false;
let lastX = 0, lastY = 0;
let currentTool = 'brush';
let currentColor = '#00d9ff';
let brushSize = 4;
let undoStack = [];
let startX = 0, startY = 0;

function saveState() {
  undoStack.push(canvas.toDataURL());
  if (undoStack.length > 50) undoStack.shift();
}

function restoreState(dataUrl) {
  const img = new Image();
  img.onload = () => {
    ctx.clearRect(0, 0, WIDTH, HEIGHT);
    ctx.drawImage(img, 0, 0);
  };
  img.src = dataUrl;
}

function undo() {
  if (undoStack.length === 0) return;
  const state = undoStack.pop();
  restoreState(state);
}

function clearCanvas() {
  if (!confirm('Clear the entire drawing?')) return;
  saveState();
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, WIDTH, HEIGHT);
}

function setTool(tool) {
  currentTool = tool;
  document.querySelectorAll('[data-tool]').forEach(b => b.classList.toggle('active', b.dataset.tool === tool));
  canvas.style.cursor = tool === 'eraser' ? 'cell' : 'crosshair';
}

function getPos(e) {
  const rect = canvas.getBoundingClientRect();
  const scaleX = canvas.width / rect.width;
  const scaleY = canvas.height / rect.height;
  const x = (e.clientX || e.touches[0].clientX) - rect.left;
  const y = (e.clientY || e.touches[0].clientY) - rect.top;
  return { x: x * scaleX, y: y * scaleY };
}

function startDrawing(e) {
  e.preventDefault();
  isDrawing = true;
  const pos = getPos(e);
  lastX = pos.x; lastY = pos.y;
  startX = pos.x; startY = pos.y;
  saveState();

  if (currentTool === 'brush' || currentTool === 'eraser') {
    ctx.beginPath();
    ctx.moveTo(lastX, lastY);
  }
}

function draw(e) {
  e.preventDefault();
  const pos = getPos(e);
  document.getElementById('coordDisplay').textContent = `📍 (${Math.round(pos.x)}, ${Math.round(pos.y)})`;

  if (!isDrawing) return;

  if (currentTool === 'brush' || currentTool === 'eraser') {
    ctx.strokeStyle = currentTool === 'eraser' ? '#ffffff' : currentColor;
    ctx.lineWidth = brushSize;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.lineTo(pos.x, pos.y);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(pos.x, pos.y);
  } else if (currentTool === 'line') {
    restoreState(undoStack[undoStack.length - 1]);
    ctx.strokeStyle = currentColor;
    ctx.lineWidth = brushSize;
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(pos.x, pos.y);
    ctx.stroke();
  } else if (currentTool === 'rect') {
    restoreState(undoStack[undoStack.length - 1]);
    ctx.fillStyle = currentColor;
    ctx.globalAlpha = 0.2;
    ctx.fillRect(startX, startY, pos.x - startX, pos.y - startY);
    ctx.globalAlpha = 1;
    ctx.strokeStyle = currentColor;
    ctx.lineWidth = brushSize / 2;
    ctx.strokeRect(startX, startY, pos.x - startX, pos.y - startY);
  } else if (currentTool === 'circle') {
    restoreState(undoStack[undoStack.length - 1]);
    const rx = Math.abs(pos.x - startX) / 2;
    const ry = Math.abs(pos.y - startY) / 2;
    const cx = startX + (pos.x - startX) / 2;
    const cy = startY + (pos.y - startY) / 2;
    ctx.fillStyle = currentColor;
    ctx.globalAlpha = 0.2;
    ctx.beginPath();
    ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.strokeStyle = currentColor;
    ctx.lineWidth = brushSize / 2;
    ctx.beginPath();
    ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
    ctx.stroke();
  }

  lastX = pos.x; lastY = pos.y;
}

function stopDrawing(e) {
  if (!isDrawing) return;
  isDrawing = false;
  ctx.beginPath();
}

