package game

// GameStatus tracks the state of a chess match.
type GameStatus int

const (
	Setup GameStatus = iota
	Playing
	Check
	Checkmate
	Stalemate
	Draw
)

type Color int

const (
	White Color = iota
	Black
)

type PieceType int

const (
	Pawn PieceType = iota
	Knight
	Bishop
	Rook
	Queen
	King
)

type Piece struct {
	Kind  PieceType
	Color Color
}

type Move struct {
	FromRow, FromCol int
	ToRow, ToCol     int
	Piece            Piece
	Captured         *Piece
}

// Game is the mutable board state for one match.
type Game struct {
	Board     [8][8]*Piece
	Turn      Color
	Status    GameStatus
	HalfMoves int
}

func NewGame() *Game {
	g := &Game{Turn: White, Status: Setup}
	g.Reset()
	return g
}

// Reset clears the board and restores the starting side to move.
func (g *Game) Reset() {
	for r := 0; r < 8; r++ {
		for c := 0; c < 8; c++ {
			g.Board[r][c] = nil
		}
	}
	g.Turn = White
	g.Status = Setup
	g.HalfMoves = 0
}

// MovePiece applies a move to the board. Legality checks live in a
// separate validation layer (move generation); this only mutates state.
func (g *Game) MovePiece(m Move) bool {
	if m.FromRow < 0 || m.FromRow > 7 || m.ToRow < 0 || m.ToRow > 7 ||
		m.FromCol < 0 || m.FromCol > 7 || m.ToCol < 0 || m.ToCol > 7 {
		return false
	}
	p := g.Board[m.FromRow][m.FromCol]
	if p == nil {
		return false
	}
	g.Board[m.ToRow][m.ToCol] = p
	g.Board[m.FromRow][m.FromCol] = nil
	g.HalfMoves++
	if g.Turn == White {
		g.Turn = Black
	} else {
		g.Turn = White
	}
	g.Status = Playing
	return true
}

