function importCSV(e) {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (ev) => {
    try {
      const lines = ev.target.result.split('\n').filter(l => l.trim());
      if (lines.length < 2) { alert('CSV must have header + data rows'); return; }
      const headers = lines[0].split(',').map(h => h.trim());
      chartLabels = [];
      chartData = [];
      for (let i = 1; i < Math.min(lines.length, 21); i++) {
        const cols = lines[i].split(',').map(c => c.trim());
        if (cols.length >= 2) {
          chartLabels.push(cols[0]);
          chartData.push(parseFloat(cols[1]) || 0);
        }
      }
      document.getElementById('chartTitle').textContent = headers[0] + ' vs ' + headers[1];
      renderChart();
      updateDataPreview();
    } catch { alert('Failed to parse CSV. Format: label,value'); }
  };
  reader.readAsText(file);
  e.target.value = '';
}

