function resizeGrid(n){
  gridSize=n;
  cellSize=parseInt(document.getElementById('zoomSelect').value)||20;
  canvas.width=gridSize*cellSize;
  canvas.height=gridSize*cellSize;
  if(pixels.length!==gridSize*gridSize){
    const newPixels=Array(gridSize*gridSize).fill(false);
    const oldSize=Math.round(Math.sqrt(pixels.length));
    for(let y=0;y<Math.min(oldSize,gridSize);y++)for(let x=0;x<Math.min(oldSize,gridSize);x++){
      newPixels[y*gridSize+x]=pixels[y*oldSize+x]||false;
    }
    pixels=newPixels;
  }
  drawGrid();
}

function setTool(t){tool=t;document.querySelectorAll('.tool-box .active').forEach(b=>b.classList.remove('active'));const ids={pencil:'pencilBtn',eraser:'eraserBtn',fill:'fillBtn',eyedropper:'eyedropperBtn'};document.getElementById(ids[t])?.classList.add('active')}

function updatePrimary(c){primaryColor=c;document.getElementById('primaryColor').value=c}
