const DIFFICULTY_TIMES = { short: 15, medium: 30, long: 60 };

let currentDifficulty = 'short';
let currentText = '';
let typedText = '';
let timerInterval = null;
let timeLeft = 15;
let isRunning = false;
let charIndex = 0;
let errors = 0;
let totalTyped = 0;
let isTestComplete = false;

function setDifficulty(diff) {
  if (isRunning) return;
  currentDifficulty = diff;
  document.querySelectorAll('.diff-btn').forEach(b => b.classList.toggle('active', b.dataset.text === diff));
  resetDisplay();
}

function getRandomText() {
  const texts = TEXTS[currentDifficulty];
  let text = texts[Math.floor(Math.random() * texts.length)];
  // Ensure unique text each time
  if (text === currentText && texts.length > 1) {
    text = texts.find(t => t !== currentText) || text;
  }
  return text;
}

function resetDisplay() {
  currentText = getRandomText();
  typedText = '';
  charIndex = 0;
  errors = 0;
  totalTyped = 0;
  timeLeft = DIFFICULTY_TIMES[currentDifficulty];
  isTestComplete = false;

  document.getElementById('wpm').textContent = '0';
  document.getElementById('accuracy').textContent = '100%';
  document.getElementById('timer').textContent = timeLeft + 's';
  document.getElementById('charCount').textContent = '0/' + currentText.length;
  document.getElementById('results').classList.remove('show');
  document.getElementById('startBtn').textContent = '🚀 Start Test';

  renderText();
}

function renderText() {
  const display = document.getElementById('textDisplay');
  display.innerHTML = currentText.split('').map((char, i) => {
    let cls = 'pending';
    if (i < charIndex) {
      cls = typedText[i] === char ? 'correct' : 'incorrect';
    } else if (i === charIndex && isRunning) {
      cls = 'current';
    }
    const displayChar = char === ' ' ? ' ' : char;
    return `<span class="char ${cls}">${displayChar}</span>`;
  }).join('');

  // Scroll to current position
  const currentEl = display.querySelector('.char.current');
  if (currentEl) {
    currentEl.scrollIntoView({ block: 'center', behavior: 'smooth' });
  }
}

function startTest() {
  resetDisplay();
  isRunning = true;
  isTestComplete = false;
  timeLeft = DIFFICULTY_TIMES[currentDifficulty];
  charIndex = 0;
  errors = 0;
  totalTyped = 0;
  typedText = '';

  document.getElementById('startBtn').textContent = '⌨️ Typing...';
  document.getElementById('hiddenInput').disabled = false;
  document.getElementById('hiddenInput').value = '';
  document.getElementById('hiddenInput').focus();

  var startTime = Date.now();
  var testDuration = DIFFICULTY_TIMES[currentDifficulty] * 1000;
  timerInterval = setInterval(() => {
    var elapsed = Date.now() - startTime;
    var remaining = Math.max(0, Math.ceil((testDuration - elapsed) / 1000));
    timeLeft = remaining;
    document.getElementById('timer').textContent = remaining + 's';
    if (remaining <= 0) {
      timeLeft = 0;
      endTest();
    }
  }, 200);

  renderText();
}

function handleInput(e) {
  if (!isRunning || isTestComplete) return;

  const input = document.getElementById('hiddenInput');
  const value = input.value;

  // Handle backspace
  if (value.length < typedText.length) {
    typedText = typedText.slice(0, -1);
    charIndex = typedText.length;
    input.value = typedText;
    renderText();
    updateStats();
    return;
  }

  if (charIndex >= currentText.length) {
    // End of text reached
    endTest();
    return;
  }

  const newChar = value[value.length - 1];
  typedText += newChar;
  totalTyped++;

  if (newChar !== currentText[charIndex]) {
    errors++;
  }

  charIndex++;
