function parseRule(rule){
  // Format: IF cond1 AND cond2 IS conclusion
  const match=rule.match(/^IF\s+(.+)\s+IS\s+(.+)$/i);
  if(!match)return null;
  const conditions=match[1].split(/\s+AND\s+/i).map(s=>s.trim().toLowerCase());
  const conclusion=match[2].trim().toLowerCase();
  return{conditions,conclusion};
}

function runForwardChain(){
  const log=document.getElementById('inferenceLog');
  log.innerHTML='';inferred=new Set();
  const derived=new Set(facts);
  let changed=true,iterations=0;
  log.innerHTML+=`<div class="inf">▶ Starting forward chaining...</div>`;
  log.innerHTML+=`<div class="fac">  Initial facts: ${[...derived].map(escapeHTML).join(', ')}</div>`;

  while(changed&&iterations<50){
    changed=false;iterations++;
    for(const rule of rules){
      const parsed=parseRule(rule);
      if(!parsed){      log.innerHTML+=`<div>  ⚠️ Invalid rule: ${escapeHTML(rule)}</div>`;continue}
      const allMatch=parsed.conditions.every(c=>derived.has(c));
      if(allMatch&&!derived.has(parsed.conclusion)&&!inferred.has(parsed.conclusion)){
        derived.add(parsed.conclusion);inferred.add(parsed.conclusion);changed=true;
        log.innerHTML+=`<div class="fac">  ✅ Inferred: ${escapeHTML(parsed.conclusion)}</div>`;
      }
    }
  }

  facts=[...derived];
  log.innerHTML+=`<div class="inf">⏹ Done (${iterations} iterations)</div>`;
  log.innerHTML+=`<div class="fac">  Total facts: ${facts.length}, New: ${inferred.size}</div>`;
  render();saveToStorage();
}

