function solve(){
  resetBoard();solving=true;
  document.getElementById('solutionsDisplay').textContent='🔄 Searching...';
  setTimeout(()=>{
    const allSolutions=[];
    function backtrack(row){steps++;if(row===N){allSolutions.push([...board]);return}
      for(let col=0;col<N;col++){if(isSafe(board,row,col)){board[row]=col;backtrack(row+1);board[row]=-1;backtracks++}}
    }
    backtrack(0);
    solutions=allSolutions;
    if(solutions.length>0){currentSolution=0;board=[...solutions[0]];draw()}
    document.getElementById('solutionsDisplay').textContent=solutions.length;
    document.getElementById('solutionDisplay').textContent=`Solution: ${solutions.length>0?1:0}/${solutions.length}`;
    updateStats();solving=false;saveToStorage();
  },50);
}

function stepSolve(){
  if(!solving){
    steps=0;backtracks=0;board=Array(N).fill(-1);solving=true;
    stepQueue=[];buildStepQueue(0);
    if(stepQueue.length===0){solving=false;return}
  }
  if(stepQueue.length===0){document.getElementById('solutionsDisplay').textContent='✅ Complete';solving=false;return}
  const action=stepQueue.shift();
  if(action.type==='place'){board[action.row]=action.col;steps++}
  else if(action.type==='remove'){board[action.row]=-1;backtracks++}
  draw();updateStats();
  if(stepQueue.length===0){document.getElementById('solutionsDisplay').textContent='✅ Complete'}
}

function buildStepQueue(row){
  if(row===N){stepQueue.push({type:'place',row:-1,col:-1});return}
  for(let col=0;col<N;col++){
    if(isSafe(board,row,col)){stepQueue.push({type:'place',row,col});board[row]=col;buildStepQueue(row+1);board[row]=-1;stepQueue.push({type:'remove',row,col})}
  }
}

function nextSolution(){
  if(solutions.length===0)return;
  currentSolution=(currentSolution+1)%solutions.length;
  board=[...solutions[currentSolution]];draw();
  document.getElementById('solutionDisplay').textContent=`Solution: ${currentSolution+1}/${solutions.length}`;
}

function prevSolution(){
  if(solutions.length===0)return;
  currentSolution=(currentSolution-1+solutions.length)%solutions.length;
  board=[...solutions[currentSolution]];draw();
  document.getElementById('solutionDisplay').textContent=`Solution: ${currentSolution+1}/${solutions.length}`;
}

function draw(){
  const size=Math.min(500,500);canvas.width=size;canvas.height=size;
  const cell=size/N;
  for(let r=0;r<N;r++)for(let c=0;c<N;c++){
    ctx.fillStyle=(r+c)%2===0?'#1a1a2e':'#0e0e1a';
    ctx.fillRect(c*cell,r*cell,cell,cell);
  }
  for(let r=0;r<N;r++){
    if(board[r]>=0){
      const c=board[r],x=c*cell+cell/2,y=r*cell+cell/2;
      ctx.font=`${cell*0.6}px Arial`;ctx.textAlign='center';ctx.textBaseline='middle';
      ctx.fillText('👑',x,y+2);
      // Highlight
      ctx.fillStyle='rgba(0,217,255,0.06)';ctx.fillRect(c*cell,r*cell,cell,cell);
    }
  }
  // Grid lines
  ctx.strokeStyle='rgba(255,255,255,0.06)';ctx.lineWidth=0.5;
  for(let i=0;i<=N;i++){ctx.beginPath();ctx.moveTo(i*cell,0);ctx.lineTo(i*cell,size);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i*cell);ctx.lineTo(size,i*cell);ctx.stroke()}
}

