function getCanvasPos(e) {
  const rect = canvas.getBoundingClientRect();
  const scaleX = canvas.width / rect.width;
  const scaleY = canvas.height / rect.height;
  const t = e.touches ? e.touches[0] : e;
  return { x: (t.clientX - rect.left) * scaleX, y: (t.clientY - rect.top) * scaleY };
}

function startDraw(e) {
  e.preventDefault();
  const pos = getCanvasPos(e);
  isDrawing = true;
  startX = pos.x; startY = pos.y;
  if (currentTool === 'pen' || currentTool === 'eraser') {
    elements.push({ type: currentTool, points: [pos], color: currentTool === 'eraser' ? '#1a1a2e' : currentColor, size: currentSize });
  } else if (currentTool === 'text') {
    placeText(pos);
    isDrawing = false;
  }
}

function moveDraw(e) {
  e.preventDefault();
  if (!isDrawing) return;
  const pos = getCanvasPos(e);
  const last = elements[elements.length - 1];
  if (currentTool === 'pen' || currentTool === 'eraser') {
    last.points.push(pos);
    redraw();
  } else {
    last.x2 = pos.x; last.y2 = pos.y;
    redraw();
  }
}

function endDraw(e) {
  if (!isDrawing) return;
  isDrawing = false;
  const last = elements[elements.length - 1];
  if (last && (last.type === 'line' || last.type === 'rect' || last.type === 'circle')) {
    if (Math.abs(last.x2 - last.x1) < 3 && Math.abs(last.y2 - last.y1) < 3) {
      elements.pop();
    }
  }
  undoStack.push(elements.length);
  redraw();
}

function placeText(pos) {
  const text = prompt('Enter text:', 'Hello');
  if (text) {
    elements.push({ type: 'text', x: pos.x, y: pos.y, text, color: currentColor, size: currentSize });
    undoStack.push(elements.length);
    redraw();
  }
}

function setTool(tool) {
  currentTool = tool;
  document.querySelectorAll('.tool-btn').forEach(b => b.classList.toggle('active', b.dataset.tool === tool));
  canvas.style.cursor = tool === 'text' ? 'text' : tool === 'eraser' ? 'cell' : 'crosshair';
  renderProps();
}

function setColor(color) {
  currentColor = color;
  document.querySelectorAll('.color-btn').forEach(b => b.classList.toggle('active', b.dataset.color === color));
  renderProps();
}

function undo() {
  const prev = undoStack.length > 1 ? undoStack[undoStack.length - 2] : 0;
  elements = elements.slice(0, prev);
  undoStack.pop();
  redraw();
}

function clearCanvas() {
  if (elements.length === 0) return;
  if (!confirm('Clear the entire whiteboard?')) return;
  elements = [];
  undoStack = [];
  redraw();
}

function renderProps() {
  const size = document.getElementById('brushSize').value;
  currentSize = parseInt(size);
  const toolNames = { pen: 'Pen', line: 'Line', rect: 'Rectangle', circle: 'Circle', eraser: 'Eraser', text: 'Text' };
  document.getElementById('propTool').textContent = toolNames[currentTool] || currentTool;
