function createLayer(name, w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return { canvas: c, ctx: c.getContext('2d'), name, visible: true, opacity: 1, blendMode: 'source-over' };
}

function initCanvas() {
  const w = 800, h = 600;
  canvas.width = w; canvas.height = h;

  // Background layer
  const bg = createLayer('Background', w, h);
  bg.ctx.fillStyle = '#ffffff';
  bg.ctx.fillRect(0, 0, w, h);
  layers.push(bg);

  // Drawing layer
  const draw = createLayer('Layer 1', w, h);
  layers.push(draw);

  activeLayerIndex = 1;
  renderComposite();
  renderLayers();
}

function getActiveLayer() { return layers[activeLayerIndex]; }

function addLayer() {
  const name = `Layer ${layers.length}`;
  const l = createLayer(name, canvas.width, canvas.height);
  layers.push(l);
  activeLayerIndex = layers.length - 1;
  renderLayers();
  renderComposite();
}

function duplicateLayer() {
  const src = getActiveLayer();
  if (!src) return;
  const c = createLayer(src.name + ' copy', canvas.width, canvas.height);
  c.ctx.drawImage(src.canvas, 0, 0);
  layers.splice(activeLayerIndex + 1, 0, c);
  activeLayerIndex++;
  renderLayers();
  renderComposite();
}

function mergeLayer() {
  if (layers.length < 2 || activeLayerIndex < 1) return;
  const src = layers[activeLayerIndex];
  const dst = layers[activeLayerIndex - 1];
  dst.ctx.drawImage(src.canvas, 0, 0);
  layers.splice(activeLayerIndex, 1);
  activeLayerIndex--;
  renderLayers();
  renderComposite();
}

function deleteLayer() {
  if (layers.length <= 1) return;
  layers.splice(activeLayerIndex, 1);
  activeLayerIndex = Math.min(activeLayerIndex, layers.length - 1);
  renderLayers();
  renderComposite();
}

function toggleLayerVisibility(idx) {
  layers[idx].visible = !layers[idx].visible;
  renderLayers();
  renderComposite();
}

function selectLayer(idx) {
  activeLayerIndex = idx;
  renderLayers();
}

function updateLayerOpacity(idx, val) {
  layers[idx].opacity = parseFloat(val);
  renderComposite();
}

// ── COMPOSITE ──
function renderComposite() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const layer of layers) {
    if (!layer.visible) continue;
    ctx.globalAlpha = layer.opacity;
    ctx.globalCompositeOperation = layer.blendMode || 'source-over';
    ctx.drawImage(layer.canvas, 0, 0);
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
}

