},'Change directory');

register('mkdir',(args)=>{
  if(!args[0]){print('mkdir: missing operand','err');return}
  const parts=args[0].split('/').filter(Boolean);
  const dirName=parts.pop();
  const parentPath=resolvePath(parts.join('/')||'.');
  const parent=getNode(parentPath);
  if(!parent||parent.type!=='dir'){print(`mkdir: cannot create directory '${args[0]}': No such file or directory`,'err');return}
  if(parent.children[dirName]){print(`mkdir: cannot create directory '${args[0]}': File exists`,'err');return}
  parent.children[dirName]={type:'dir',children:{}};
},'Create directory');

register('touch',(args)=>{
  if(!args[0]){print('touch: missing operand','err');return}
  const parts=args[0].split('/').filter(Boolean);
  const fileName=parts.pop();
  const parentPath=resolvePath(parts.join('/')||'.');
  const parent=getNode(parentPath);
  if(!parent||parent.type!=='dir'){print(`touch: cannot touch '${args[0]}': No such file or directory`,'err');return}
  if(!parent.children[fileName])parent.children[fileName]={type:'file',content:''};
