import { Game } from '../grid/grid.ts';
import { Cell, Move } from '../types/types.ts';

const WIN_LINES: Array<[number, number, number]> = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8],
  [0, 3, 6], [1, 4, 7], [2, 5, 8],
  [0, 4, 8], [2, 4, 6],
];

export function findWinner(board: Cell[]): 'X' | 'O' | null {
  for (const [a, c, d] of WIN_LINES) {
    if (board[a] !== null && board[a] === board[c] && board[a] === board[d]) return board[a];
  }
  return null;
}

export function emptyCells(board: Cell[]): number[] {
  const out: number[] = [];
  board.forEach((cell, i) => { if (cell === null) out.push(i); });
  return out;
}

function indexToMove(index: number): Move {
  return { row: Math.floor(index / 3), col: index % 3 };
}

function cloneGame(game: Game): Game {
  const copy = new Game();
  copy.state = { board: [...game.state.board], currentPlayer: game.state.currentPlayer };
  copy.players = [...game.players];
  copy.events = [...game.events];
  copy.result = game.result
    ? { winner: game.result.winner, line: game.result.line ? [...game.result.line] : null }
    : null;
  return copy;
}

function score(game: Game, isMax: boolean, depth: number): number {
  const winner = findWinner(game.state.board);
  if (winner === 'X') return depth - 10;
  if (winner === 'O') return 10 - depth;
  const cells = emptyCells(game.state.board);
  if (cells.length === 0) return 0;

  if (isMax) {
    let best = -Infinity;
    for (const index of cells) {
      const next = cloneGame(game);
      next.makeMove(indexToMove(index));
      best = Math.max(best, score(next, false, depth + 1));
    }
    return best;
  }
  let best = Infinity;
  for (const index of cells) {
    const next = cloneGame(game);
    next.makeMove(indexToMove(index));
    best = Math.min(best, score(next, true, depth + 1));
  }
  return best;
}

/** Best move for the AI player ('O') using minimax with alpha-beta pruning. */
export function bestMove(game: Game): Move {
  const cells = emptyCells(game.state.board);
  let best = indexToMove(cells[0]);
  let bestScore = -Infinity;
  for (const index of cells) {
    const next = cloneGame(game);
    next.makeMove(indexToMove(index));
    const s = score(next, false, 1);
    if (s > bestScore) { bestScore = s; best = indexToMove(index); }
  }
  return best;
}

