  const chartW = w - pad.left - pad.right;
  const chartH = h - pad.top - pad.bottom;

  const values = data.map(d => d.value);
  const min = Math.min(...values) * 0.95;
  const max = Math.max(...values) * 1.05;
  const xScale = chartW / (data.length - 1);
  const yScale = chartH / (max - min);

  // Grid lines
  let gridHtml = '';
  for (let i = 0; i <= 4; i++) {
    const y = pad.top + (chartH / 4) * i;
    const val = max - ((max - min) / 4) * i;
    gridHtml += `<line class="grid-line" x1="${pad.left}" y1="${y}" x2="${w - pad.right}" y2="${y}"/>`;
    gridHtml += `<text class="y-label" x="${pad.left - 5}" y="${y + 3}" text-anchor="end">$${Math.round(val / 1000)}k</text>`;
  }

  // Data points
  const points = data.map((d, i) => ({
    x: pad.left + i * xScale,
    y: pad.top + chartH - (d.value - min) * yScale,
  }));

  const linePath = points.map((p, i) => `${i === 0 ? 'M' : 'L'}${p.x},${p.y}`).join(' ');
  const areaPath = linePath + ` L${points[points.length - 1].x},${pad.top + chartH} L${points[0].x},${pad.top + chartH} Z`;

  // X-axis labels
  let xLabels = '';
  const step = Math.max(1, Math.floor(data.length / 8));
  for (let i = 0; i < data.length; i += step) {
    const d = data[i].date;
    xLabels += `<text class="dot-label" x="${points[i].x}" y="${h - 4}">${d.getMonth() + 1}/${d.getDate()}</text>`;
  }

  svg.innerHTML = `
    <defs>
      <linearGradient id="gradient" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#00d9ff" stop-opacity="0.3"/>
        <stop offset="100%" stop-color="#00d9ff" stop-opacity="0"/>
      </linearGradient>
    </defs>
    ${gridHtml}
    <path class="data-area" d="${areaPath}"/>
    <path class="data-line" d="${linePath}" stroke="#00d9ff"/>
    ${points.map((p, i) => `<circle class="dot" cx="${p.x}" cy="${p.y}" r="3" stroke="#00d9ff"><title>$${data[i].value.toLocaleString()}</title></circle>`).join('')}
    ${xLabels}
  `;
