const GRID_SIZE=9,BOX_SIZE=3;
let board=[],given=Array(9).fill(null).map(()=>Array(9).fill(false));
let stepCount=0,backtrackCount=0,solving=false,solveQueue=[];
const PUZZLES={
  easy:['530070000600195000098000060800060003400803001700020006060000280000419005000080079',
        '000260701680070090190004500820100040004602900050003028009300074040050036703018000'],
  medium:['000000000000003085001020000000507000004000100090000000500000073002010000000040009',
          '020000000000600003074000800000020060080004000010000500000007001000080000009000040'],
  hard:['800000000003600000070090200050007000000045700000100030001000068008500010090000400',
