  board=Array(9).fill(null).map(()=>Array(9).fill(0));
  given=Array(9).fill(null).map(()=>Array(9).fill(false));
  for(let i=0;i<81;i++){const r=Math.floor(i/9),c=i%9;const val=parseInt(puzzleStr[i]);if(val){board[r][c]=val;given[r][c]=true}}
  solving=false;stepIndex=0;stepCount=0;backtrackCount=0;
  document.getElementById('solveStatus').textContent='Ready';
  document.querySelectorAll('.diff-btn').forEach(b=>b.classList.toggle('active',b.dataset.diff===diff));
  renderBoard();
}

