function validateBoard(){
  readBoard();let valid=true;
  for(let r=0;r<GRID_SIZE;r++)for(let c=0;c<GRID_SIZE;c++){
    if(board[r][c]!==0){const num=board[r][c];board[r][c]=0;if(!isValid(board,r,c,num)){valid=false;document.querySelector(`.cell[data-r="${r}"][data-c="${c}"]`).classList.add('conflict')}board[r][c]=num}
  }
